				tc.mutate(t, ver)
			})
			// The candidate (twin) is itself intact; its legality must not
			// rescue the damaged historical declaration.
			assertCompareRefused(t, dir, "1", "0xblk", "twin", "candC", tc.wantErr)
		})
	}
